{"content":"from itertools import combinations
import networkx as nx

def realize(ds):
 n=len(ds); ds=list(ds); E=[]
 def rec(i):
  while i<n and ds[i]==0:i+=1
  if i==n:
   yield E.copy();return
  cand=[j for j in range(i+1,n) if ds[j]>0]
  d=ds[i]
  if d>len(cand):return
  ds[i]=0
  for S in combinations(cand,d):
   for j in S:ds[j]-=1
   E.extend((i,j) for j in S)
   if all(ds[j]<=sum(ds[k]>0 for k in range(j+1,n))+sum(ds[k]>0 for k in range(i+1,j)) for j in range(i+1,n)):
    yield from rec(i+1)
   del E[-d:]
   for j in S:ds[j]+=1
  ds[i]=d
 yield from rec(0)
for n in (5,7):
 reps=[];total=0
 for es in realize([2]+[3]*(n-1)):
  G=nx.Graph();G.add_nodes_from(range(n));G.add_edges_from(es)
  if not nx.is_connected(G):continue
  total+=1
  if not any(nx.is_isomorphic(G,H) for H in reps): reps.append(G)
 print(n,total,len(reps))
"}

